"""Generate the static resource pages. Run from the repository root with Python 3."""
from pathlib import Path
import json, re, html, subprocess
ROOT=Path(__file__).resolve().parents[1]
PUBLIC=ROOT/'public'
SITE=json.loads((ROOT/'content/site.json').read_text())
BRAND=SITE['brandName']
DATA=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import {guides,releases} from './scripts/resource-content.mjs'; import {clockxPlan,fullWorkspacePlan} from './public/pricing.js'; console.log(JSON.stringify({guides,releases,clockx:[5,10,20].map(clockxPlan),full:[5,15,30,50].map(fullWorkspacePlan)}))"],cwd=ROOT,text=True))
esc=lambda value:html.escape(str(value),quote=True)
ARROW='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>'
DOWNLOAD='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5"/></svg>'
ICONS={
 'help':'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4V4Zm16 0h-4a3 3 0 0 0-3 3m0 14a4 4 0 0 1 4-3h3V4"/>',
 'security':'<path d="m12 3 8 4v6c0 4-8 8-8 8s-8-4-8-8V7l8-4Z"/><path d="m8 12 3 3 5-6"/>',
 'switching':'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',
 'updates':'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-2l2 2M4 17l2 2a7 7 0 0 0 12-2"/>',
 'subscriptions':'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m3 0h2"/>',
 'referrals':'<circle cx="8" cy="8" r="3"/><path d="M2 21v-3a6 6 0 0 1 12 0v3m2-14h6m-3-3v6m-2 4a5 5 0 0 1 5 5v2"/>',
 'brochure':'<path d="M6 3h8l4 4v14H6V3Zm8 0v5h4M9 12h6m-6 4h6"/>'}
def icon(key):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICONS.get(key,ICONS['help'])+'</svg>'
def link(href,label,cls='inline-link',download=False):return '<a class="'+cls+'" href="'+href+'"'+(' download' if download else '')+'>'+label+' '+(DOWNLOAD if download else ARROW)+'</a>'
def note(title,text):return '<aside class="resource-note"><b>'+title+'</b><p>'+text+'</p></aside>'
def hero(label,title,description,aside=''):
 return '<section class="resource-hero wrap'+(' has-aside' if aside else '')+'"><div data-reveal><span class="eyebrow">'+label+'</span><h1>'+title+'</h1><p>'+description+'</p></div>'+aside+'</section>'
def card(path,title,description,kicker='',kind='help',extra=''):
 action={'/help/':'Find a guide','/security/':'Understand access','/brochure/':'View the brochure','/switching/':'Read the switching guide','/updates/':'See product updates','/subscriptions/':'Understand subscriptions','/referrals/':'Create an introduction link'}.get(path,'Explore '+title.lower())
 return '<article class="resource-card" data-reveal><span class="resource-icon">'+icon(kind)+'</span>'+('<span class="label">'+kicker+'</span>' if kicker else '')+'<h3>'+title+'</h3><p>'+description+'</p>'+extra+link(path,action)+'</article>'
def cta(title='A little guidance.<br>A clearer next step.',text='Explore the platform, compare packages or prepare a question for us.'):
 return '<section class="wrap resource-bottom-cta" data-reveal><div><span class="eyebrow">HERE TO HELP YOU GET STARTED</span><h2>'+title+'</h2><p>'+text+'</p></div><div>'+link('/pricing/','Compare packages','button button-dark')+link('/contact/','Prepare an enquiry','button button-outline')+'</div></section>'
def faq(items):return '<div class="resource-faq">'+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in items)+'</div>'
TEMPLATE=(PUBLIC/'about/index.html').read_text()
HEADER=re.search(r'<header class="site-header".*?</header>',TEMPLATE,re.S).group(0)
FOOTER=re.search(r'<footer class="site-footer".*?</footer>',TEMPLATE,re.S).group(0)
HEAD=TEMPLATE[:TEMPLATE.index('</head>')]
PAGES={}
def page(path,title,description,content):
 head=re.sub(r'<title>.*?</title>','<title>'+esc(title+' - '+BRAND)+'</title>',HEAD)
 head=re.sub(r'(<meta (?:name="description"|property="og:description") content=")[^"]*',lambda m:m.group(1)+esc(description),head)
 head=re.sub(r'(<meta property="og:title" content=")[^"]*',lambda m:m.group(1)+esc(title+' - '+BRAND),head)
 head=head.replace(SITE['websiteURL']+'about/',SITE['websiteURL']+path)
 header=re.sub(r' aria-current="page"','',HEADER)
 PAGES[path]=head+'</head><body data-page="resources"><a class="skip-link" href="#main">Skip to content</a>'+header+'<main id="main" tabindex="-1">'+content+'</main>'+FOOTER+'</body></html>\n'

# A navigable home for all seven requested additions.
resource_items=[('help/','Help centre','Practical guides to the tools you already have.','GUIDES FOR YOUR WORKING DAY','help'),('security/','Security & data','Understand account access, private documents and the primary database location.','CLEAR INFORMATION','security'),('brochure/','Product brochure','A concise downloadable guide to packages, employee tiers and monthly add-ons.','TAKE A CLOSER LOOK','brochure'),('switching/','Switching to us','A manageable path from existing records to your first published rota.','START WITH YOUR TEAM','switching'),('updates/','Product updates','See what is available and which ideas are being considered.','THE PRODUCT, IN PROGRESS','updates'),('subscriptions/','Subscriptions explained','Annual access, employee allowances, approvals and monthly extras.','KNOW YOUR AGREEMENT','subscriptions'),('referrals/','Recommend a business','Share a referral link and carry the introduction into an enquiry.','PASS IT ON','referrals')]
resource_cards=''.join(card('/'+path,title,desc,kicker,kind) for path,title,desc,kicker,kind in resource_items)
page('resources/','Resources & support','Find help guides, security information, package guidance, product updates and the DayRidge brochure.',hero('RESOURCES & SUPPORT','A clearer answer.<br><span class="purple">A confident next step.</span>','Whether you’re exploring the platform or organising your first working week, start here.','<aside class="resource-hero-aside" data-reveal><img src="/assets/dayridge-mark.svg?v=4" alt="" width="65" height="65"><span class="label">MADE FOR THE EVERYDAY</span><h2>A little guidance.<br>A lot more clarity.</h2><p>Practical help, straightforward information and the details behind your workspace.</p></aside>')+'<section class="wrap resource-priority-strip"><span>Start here</span><a href="/help/">Find a guide '+ARROW+'</a><a href="/security/">Understand access '+ARROW+'</a><a href="/brochure/">Take the brochure '+DOWNLOAD+'</a></section><section class="wrap resource-card-grid">'+resource_cards+'</section>'+cta())

# Help centre and individual, linkable articles.
help_cards=''
for g in DATA['guides']:
 search=' '.join([g['title'],g['summary'],g['categoryName'],g['role'],g['package']]).lower()
 help_cards+='<article class="resource-card help-card" data-help-card data-category="'+g['category']+'" data-search="'+esc(search)+'"><div class="help-card-top"><span class="label">'+g['categoryName']+'</span><small>'+str(g['minutes'])+' MIN READ</small></div><h3><a href="/help/'+g['slug']+'/">'+g['title']+'</a></h3><p>'+g['summary']+'</p><span class="resource-package">'+esc(g['package'])+'</span>'+link('/help/'+g['slug']+'/','Read guide')+'</article>'
help_controls='<section class="wrap help-controls" aria-label="Find a help guide"><label class="help-search">Search the guides<input type="search" placeholder="Try rota, contracts or stock…" data-help-search autocomplete="off"></label><div class="resource-filter-row" role="group" aria-label="Guide category">'+''.join('<button type="button" data-help-filter="'+v+'" aria-pressed="'+('true' if v=='all' else 'false')+'">'+label+'</button>' for v,label in [('all','All guides'),('getting-started','Getting started'),('planning','Rotas & time'),('people','People & documents'),('stock','Stock')])+'</div><p data-help-count role="status">9 guides to explore</p></section>'
page('help/','Help centre','Find practical guides for rotas, clocking, leave, contracts, payroll hours, permissions and Stock Management.',hero('THE HELP CENTRE','Good questions.<br><span class="purple">Practical answers.</span>','Find a guide for the next thing you want to do. Each one explains who it is for and which package includes the tools.')+help_controls+'<section class="wrap resource-card-grid help-grid" aria-label="Help guides">'+help_cards+'</section><section class="wrap resource-empty" data-help-empty hidden><h2>No matching guides</h2><p>Try a shorter search or choose another category.</p><button class="button button-outline" type="button" data-help-clear>Show all guides</button></section>'+cta('Still finding your feet?','Start with the switching guide, or prepare a question about the tools your business needs.'))
for g in DATA['guides']:
 steps=''.join('<li><span>'+str(i+1).zfill(2)+'</span><div><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p></div></li>' for i,(title,text) in enumerate(g['steps']))
 related=''.join(link('/help/'+slug+'/',esc(next(x['title'] for x in DATA['guides'] if x['slug']==slug))) for slug in g['related'])
 main='<div class="wrap resource-breadcrumb"><a href="/resources/">Resources</a><span>/</span><a href="/help/">Help centre</a><span>/</span><span>'+g['categoryName']+'</span></div>'+hero(g['categoryName'].upper(),esc(g['title']),esc(g['summary']))+'<section class="wrap guide-layout"><article class="guide-article"><div class="guide-metadata"><span>'+esc(g['package'])+'</span><span>'+str(g['minutes'])+' min read</span></div><div class="guide-before"><span class="label">BEFORE YOU START</span><p>'+esc(g['before'])+'</p></div><ol class="guide-steps">'+steps+'</ol>'+note('A useful detail',esc(g['note']))+'</article><aside class="guide-sidebar"><div><span class="label">WHO THIS GUIDE IS FOR</span><p>'+esc(g['role'])+'</p></div><div><span class="label">RELATED GUIDES</span>'+related+'</div><div><span class="label">CONTINUE EXPLORING</span>'+link('/help/','All help guides')+link('/pricing/','Compare packages')+'</div><small>Reviewed '+SITE['contentReviewed']+'</small></aside></section>'
 page('help/'+g['slug']+'/',g['title'],g['summary'],main)

# Factual access information; no unverified certification or recovery promises.
security_cards=[('A login for each person','Owners, Managers, Team Leaders and Employees have views shaped around their roles. Permissions are checked when business records are requested or changed.'),('Your business, your records','Business records are separated by business membership and permission checks. Employees use their own signed-in workspace to see the records shared with them.'),('Private employment documents','Employee contracts and private documents are limited to the relevant employee where shared, their creator, the Business Owner and authorised file Managers.'),('Payroll stays controlled','The Business Owner can review team payroll figures. Employees can see the personal pay information available in their view; other Managers do not receive access to team payroll rates.'),('Clearer delegated access','Full Workspace supports additional Team Leader and personnel permissions. Stock access is granted separately to authorised Managers when that add-on is enabled.'),('A record of changes','Activity history helps authorised users follow who changed shifts, timesheets and other supported business records. Stock records include an entry and change history.')]
security_grid='<section class="wrap security-controls">'+''.join('<article data-reveal><span class="resource-small-index">'+str(i+1).zfill(2)+'</span><h2>'+title+'</h2><p>'+text+'</p></article>' for i,(title,text) in enumerate(security_cards))+'</section>'
security_platform='<section class="wrap resource-split-panel"><div><span class="eyebrow">CARE FOR YOUR BUSINESS DATA</span><h2>A secure connection.<br>Clear control over access.</h2><p>DayRidge uses an encrypted HTTPS connection. Primary application data is held in '+SITE['primaryDatabaseRegion']+', with access shaped by each person’s role and permissions.</p></div><div class="resource-fact-list"><div><span>Connection</span><b>Encrypted HTTPS</b></div><div><span>Primary data location</span><b>'+SITE['primaryDatabaseRegion']+'</b></div><div><span>Record access</span><b>Role-based permissions</b></div><small>Reviewed '+SITE['contentReviewed']+'. Ask us about the data arrangements that apply to your business.</small></div></section>'
page('security/','Security & data access','Understand roles, private employee documents, owner payroll access, data separation and the primary database location.',hero('SECURITY & DATA ACCESS','The right access.<br><span class="purple">For the right people.</span>','Your working day includes information that deserves care. Here is how the existing workspace separates roles, records and responsibilities.')+security_grid+security_platform+'<section class="wrap resource-reading-section"><div><span class="eyebrow">YOUR RECORDS & YOUR BUSINESS</span><h2>Understand the details<br>before you get started.</h2></div>'+faq([('Can I download records?','The app provides CSV exports for supported rota, attendance and payroll-hour views. Available document files can be downloaded individually. Confirm the records you need when discussing your package.'),('Who do employees contact about their records?','Employees should speak to their Business Owner or an authorised Manager about employment records, corrections, access and their employer’s policies.'),('Where can I confirm retention and recovery arrangements?','Ask for the arrangements that will apply to your business before activation, including retention, recovery and any service commitments you require. This page does not set a backup-retention period or a restoration-time guarantee.'),('Is this the website privacy information?','This page explains workspace access and service information. The separate <a href="/privacy/">Website privacy page</a> explains contact form submissions, browser-based examples and referral links on this showcase.')])+'</section>'+cta('A question about your setup?','Prepare your business requirements so we can discuss the access and service arrangements you need.'))

# Switching guide: a practical process, not a promise of unsupported imports.
switch_steps=[('Choose the tools you need','Start with employee numbers and your working week. Clockx covers rotas, clocking, annual leave and payroll hours. Full Workspace also includes open shifts, extra-hours requests, contracts, company documents, onboarding, sickness and wider personnel tools. Geo Clock-in is optional for either package. Tasks and Stock are optional monthly add-ons for Full Workspace.'),('Check your existing information','Gather current employee details, working patterns, pay schedules and the documents you intend to share. Keep the original records available while you check your new workspace.'),('Agree the account setup','Confirm the package, included employees, annual price, payment arrangements and any trial end date. The Business Owner chooses who receives Manager access.'),('Add your people thoughtfully','Use existing login emails where appropriate. In Full Workspace, optional onboarding forms can be switched off when the business already holds the information.'),('Prepare the first week','Check employee roles, hours and clocking access. Full Workspace businesses can also prepare company documents. Build the rota in draft and publish it when the team is ready.'),('Review the first recorded hours','Check clock-ins, breaks and completed timesheets with your usual payroll process. Resolve recording questions early and use the help guides as your team settles in.')]
page('switching/','Switching to DayRidge','A practical guide to bringing existing team records into Clockx or Full Workspace and preparing your first working week.',hero('SWITCHING TO '+BRAND.upper(),'A manageable start.<br><span class="purple">For a busy business.</span>','Bring the information you already have. Choose the tools you need. Give your first working week a clear plan.')+'<section class="wrap switching-steps">'+''.join('<article data-reveal><span>'+str(i+1).zfill(2)+'</span><div><h2>'+title+'</h2><p>'+text+'</p></div></article>' for i,(title,text) in enumerate(switch_steps))+'</section><section class="wrap resource-checklist-panel"><div><span class="eyebrow">BRING THESE TO THE CONVERSATION</span><h2>A useful setup checklist.</h2><p>Tick off what you have ready. This checklist stays in this page and is not submitted.</p></div><div class="setup-checklist">'+''.join('<label><input type="checkbox"><span>'+text+'</span></label>' for text in ['Active employee count and who works shifts','Owner and Manager contact details','Employee details and working patterns','Pay frequency and payroll handover needs','Contracts and company policies to share','Any Stock or Tasks requirements'])+'</div></section><section class="wrap resource-reading-section">'+note('Already have the details?','Full Workspace can skip the employee onboarding form when your business already holds the information. Public file-import functionality is not part of this setup guide; ask about your existing records before planning a transfer.')+'</section>'+cta())

# Product news and an explicitly non-committal future-ideas list.
release_cards=''
for r in DATA['releases']:
 date=r['date'];datehtml='<time datetime="'+date+'">'+('21 October 2026' if date.endswith('21') else '17 October 2026' if date.endswith('17') else '16 October 2026' if date.endswith('16') else '15 October 2026')+'</time>' if date else '<span>Timing not announced</span>'
 release_cards+='<article class="release-card" data-release data-status="'+r['status']+'" data-reveal><div class="release-meta"><span class="release-status '+r['status']+'">'+('Available' if r['status']=='available' else 'Considering')+'</span>'+datehtml+'</div><span class="label">'+r['tag']+'</span><h2>'+r['title']+'</h2><p>'+r['description']+'</p>'+('<small>Future idea only. Not included in a current package; no price or release date is announced.</small>' if r['status']=='considering' else '')+'</article>'
page('updates/','Product updates & roadmap','See released DayRidge improvements and clearly labelled ideas being considered for the future.',hero('PRODUCT UPDATES & ROADMAP','See what’s changed.<br><span class="purple">See what’s next.</span>','A straightforward view of released improvements and future ideas. An idea being considered is not a delivery commitment.')+'<section class="wrap updates-controls"><div class="resource-filter-row" role="group" aria-label="Update status">'+''.join('<button type="button" data-release-filter="'+v+'" aria-pressed="'+('true' if v=='all' else 'false')+'">'+label+'</button>' for v,label in [('all','All updates'),('available','Available'),('development','In development'),('considering','Considering')])+'</div><p role="status" data-release-count>6 updates and ideas</p></section><section class="wrap release-grid">'+release_cards+'</section><section class="wrap resource-empty" data-release-empty hidden><h2>No development items announced</h2><p>Additional work is only listed here when it is ready to be announced. Explore released improvements or tell us what would help your business.</p>'+link('/contact/?topic=feedback','Share feedback','button button-outline')+'</section>'+cta('What would help your business?','Use a real example from your working day when sharing an idea for the product.'))

# Subscription information is a guide to confirmed behaviour, not invented cancellation terms.
gbp=lambda p:'£'+format(p/100,',.2f')
clockx_rows=''.join('<tr><th scope="row">Up to '+str(p['employeeLimit'])+' employees</th><td>'+gbp(p['price'])+'</td></tr>' for p in DATA['clockx'])
full_rows=''.join('<tr><th scope="row">'+('Up to 5' if p['code']=='starter' else '10–15' if p['code']=='team' else '16–30' if p['code']=='business' else '31–50')+' employees</th><td>'+gbp(p['price'])+'</td></tr>' for p in DATA['full'])
subscription_tables='<section class="wrap subscription-table-grid"><article class="resource-table-card"><span class="label">CLOCKX</span><h2>One set of tools.<br>Three employee allowances.</h2><table><caption>Clockx annual price per business</caption><thead><tr><th scope="col">Employee allowance</th><th scope="col">Per year</th></tr></thead><tbody>'+clockx_rows+'</tbody></table><p>Above 20 employees requires an agreed custom quote. The £45 Full Workspace rule does not apply to Clockx.</p></article><article class="resource-table-card"><span class="label">FULL WORKSPACE</span><h2>Wider people tools.<br>Room for a growing team.</h2><table><caption>Full Workspace annual price per business</caption><thead><tr><th scope="col">Employee allowance</th><th scope="col">Per year</th></tr></thead><tbody>'+full_rows+'</tbody></table><p>For teams of 6–9, add £45 per employee above the first five: £344.99, £389.99, £434.99 or £479.99 per year. From 10, fixed bands apply. Above 50 requires a custom quote.</p></article></section>'
subscription_faq=faq([('How are annual subscriptions paid?','Annual access is currently arranged by bank transfer. The package, employee allowance and annual price are agreed for your business. Manager access is included; a Manager with an employee profile to work shifts uses one employee place.'),('What happens above the approved employee allowance?','The Manager saves an employee request. The platform administrator reviews the plan change and charge before the new employee’s access is activated. Clockx moves from 5 to 10 places for a £70 annual increase, then from 10 to 20 for £150. Above the published tiers needs an agreed quote.'),('Will replacing an employee purchase another place?','An available place within the approved allowance can be reused. Adding a person within that allowance does not purchase another place. Working Managers with employee profiles count in the allowance.'),('How do add-ons work?','Geo Clock-in is available with Clockx and Full Workspace at £4.99 per business per month or £49.99 per business per year, covering the agreed employee allowance. Tasks costs £4.99 per business per month plus £2.35 per agreed chargeable user per month. Stock Management costs £9.99 per business per month. Tasks and Stock Management require Full Workspace. Each add-on must be enabled for the purchasing business. Tasks charges use the agreed chargeable-user count; they do not automatically follow every new employee.'),('What is recorded when a plan increases?','An approved annual increase is recorded in Finance and reflected in the annual renewal quote. The administrator can reduce an initial charge for a part year where agreed. Approval records a charge for invoicing; it does not collect a card payment.'),('How are renewals, cancellation and trials agreed?','Your business agreement should confirm the subscription start date, renewal date and quote, any trial end date, payment dates and cancellation arrangements. No standard cancellation notice period, refund rule or automatic card-renewal policy is announced on this guide. Confirm those points before activation.'),('How do I change or end an add-on?','Discuss the change with the platform team and agree the effective date and any final charge. Follow the cancellation arrangements confirmed for your business; this website does not provide a self-service cancellation action.'),('Does a website estimate activate a subscription?','No. Website estimates are for discussion. Contact form submissions are stored for the DayRidge team to review and do not activate a subscription. No email notification is sent.')])
page('subscriptions/','Subscriptions explained','Understand annual Clockx and Full Workspace access, employee approvals, renewal quotes and optional monthly add-ons.',hero('SUBSCRIPTIONS EXPLAINED','Your package.<br><span class="purple">Clearly understood.</span>','Annual access for your business. Optional monthly tools when you need them. Here is how the agreed employee allowances and charges work.')+subscription_tables+'<section class="wrap resource-reading-section"><div><span class="eyebrow">THE DETAILS BEHIND THE PRICE</span><h2>Know what happens<br>as your business grows.</h2><p>This is a product and billing guide. The order and service terms agreed with your business set your contract.</p></div>'+subscription_faq+'</section>'+cta())

# No reward amount or eligibility promise is invented before Luke confirms the offer.
referral_form='<section class="wrap referral-layout"><article class="referral-story"><span class="eyebrow">A PERSONAL INTRODUCTION</span><h2>Know a business<br>that could use this?</h2><ol><li><b>Start with someone you know.</b><p>Share the public website with a business owner or Manager who would find the tools useful.</p></li><li><b>Keep the introduction attached.</b><p>Create a link with your name or business reference. The receiving business can carry that reference into its own enquiry.</p></li><li><b>Discuss any reward before introducing.</b><p>Referral rewards, eligibility and payment or credit terms are not published yet. Agree an offer with us before relying on a reward.</p></li></ol></article><form class="referral-form" data-referral-form><span class="resource-icon">'+icon('referrals')+'</span><h2>Create your introduction link</h2><p>This creates a public website link in your browser. It does not register a referral or submit anyone’s information.</p><label>Your name or business reference<input name="referrer" required maxlength="120" autocomplete="organization" placeholder="e.g. Your business name"></label><small>Use a reference you are happy to share in the link. Do not enter employee information or another person’s contact details.</small><button type="submit" class="button button-dark">Create referral link '+ARROW+'</button><div class="referral-result" data-referral-result hidden><label>Your link<input data-referral-link type="url" readonly></label><button type="button" class="button button-outline" data-copy-referral>Copy referral link</button><p role="status" data-referral-status></p></div></form></section>'
page('referrals/','Recommend a business','Create a shareable introduction link and understand the current status of referral rewards.',hero('RECOMMEND A BUSINESS','A useful introduction.<br><span class="purple">A more connected day.</span>','If the platform could help a business you know, make an introduction they can explore in their own time.')+referral_form+'<section class="wrap resource-reading-section">'+note('Referral programme status','Introduction links are available. A financial reward programme is not open yet: no fixed reward, eligibility rules or credit terms have been announced. A link does not create a reward entitlement or confirm that a business has become a paying customer.')+'</section>'+cta('Let the business decide.','Send the website link and let the business owner choose whether to enquire.'))

# Brochure landing page. The PDF is generated and visually verified separately.
page('brochure/','Download the product brochure','Download the DayRidge product brochure with Clockx and Full Workspace packages, annual prices and monthly add-ons.',hero('THE PRODUCT BROCHURE','The full picture.<br><span class="purple">Ready to take with you.</span>','An illustrated guide to the tools, workflows, packages and prices. Keep a copy, share it with a colleague or bring it to a conversation about your business.')+'<section class="wrap brochure-layout"><div class="brochure-cover" data-reveal><img src="/assets/dayridge-logo-horizontal.svg?v=5" alt="DayRidge" width="230" height="60"><span class="label">YOUR PRODUCT GUIDE</span><h2>Your team.<br>Your time.<br><em>One place.</em></h2><div><span>Clockx</span><span>Full Workspace</span><span>Optional add-ons</span></div><small>2026/27 · Based in Suffolk</small></div><article class="brochure-details" data-reveal><span class="eyebrow">ONE GUIDE. CLEAR CHOICES.</span><h2>A useful starting point<br>for your next conversation.</h2><ul><li>Illustrated clocking, rota and leave workflows, plus Clockx employee tiers.</li><li>Full Workspace people tools, package comparison and annual employee bands.</li><li>Visual guides to Tasks and Stock Management, with monthly prices.</li><li>The Employee, Manager, Team Leader and Business Owner views.</li><li>Our values and a visual walkthrough of the working day.</li></ul>'+link('/downloads/dayridge-product-brochure.pdf?v=20261029-values','Download brochure · PDF','button button-dark',True)+'<p class="resource-download-detail">Twelve illustrated pages · Updated 29 October 2026. The guide describes current product options; your agreed business quote sets the subscription.</p>'+link('/pricing/','Explore the live pricing page')+'</article></section>'+cta())

# Write new pages, then consistently integrate navigation and shared assets everywhere.
for path,content in PAGES.items():
 target=PUBLIC/path/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
for target in PUBLIC.rglob('*.html'):
 s=target.read_text()
 if 'href="/resources/" class="nav-link"' not in s and 'href="/knowledge-base/" class="nav-link"' not in s:
  s=s.replace('<a class="nav-link" href="/pricing/">Pricing</a>','<a class="nav-link" href="/pricing/">Pricing</a>\n       <a href="/resources/" class="nav-link"'+(' aria-current="page"' if '<body data-page="resources">' in s else '')+'>Resources</a>')
 # Pricing itself has an aria-current attribute; cover that retained navigation too.
 if 'href="/resources/" class="nav-link"' not in s and 'href="/knowledge-base/" class="nav-link"' not in s:
  s=s.replace('<a class="nav-link" href="/pricing/" aria-current="page">Pricing</a>','<a class="nav-link" href="/pricing/" aria-current="page">Pricing</a>\n       <a href="/resources/" class="nav-link">Resources</a>')
 if '<body data-page="resources">' in s:
  s=re.sub(r'<a href="/resources/" class="nav-link"(?: aria-current="page")?>', '<a href="/resources/" class="nav-link" aria-current="page">',s)
 if '/resources.css' not in s:s=s.replace('<link rel="stylesheet" href="/polish.css">','<link rel="stylesheet" href="/polish.css">\n <link rel="stylesheet" href="/resources.css">')
 if '/resources.js' not in s:s=s.replace('</head>','<script type="module" src="/resources.js?v=1"></script>\n</head>')
 s=s.replace('/main.js?v=9','/main.js?v=10')
 old='<a href="/about/">About us</a></nav>'
 if old in s:s=s.replace(old,'<a href="/about/">About us</a><a href="/resources/">Resources & support</a><a href="/help/">Help centre</a><a href="/security/">Security & data</a></nav>')
 if '<a href="/brochure/">Product brochure</a>' not in s:
  s=s.replace('<a href="/contact/?topic=demo">Arrange a walkthrough</a>','<a href="/contact/?topic=demo">Arrange a walkthrough</a><a href="/brochure/">Product brochure</a><a href="/referrals/">Recommend a business</a>')
 s=re.sub(r'(<div class="footer-legal">.*?</div>)',lambda m:m[0] if '<a href="/subscriptions/">Subscriptions</a>' in m[0] else m[0].replace('<a href="/privacy/">Website privacy</a>','<a href="/privacy/">Website privacy</a><a href="/subscriptions/">Subscriptions</a>'),s)
 target.write_text(s)
# New pages belong in the crawlable website map.
sitemap=PUBLIC/'sitemap.xml'
urls=[SITE['websiteURL']+p for p in ['', 'features/','pricing/','add-ons/','about/','contact/','privacy/',*PAGES.keys()]]
sitemap.write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>'+esc(url)+'</loc></url>\n' for url in dict.fromkeys(urls))+'</urlset>\n')
print('Generated',len(PAGES),'resource and help pages for',BRAND)
